import React from "react";
import classes from "./Cart.module.css";
import { motion } from "framer-motion";
import Hamburguer from "../Header/HamburguerIcon";
import { cartActions } from "../../store/cart-slice";
import { uiActions } from "../../store/ui-slice";
import PersonalDetail from "./PersonalDetail";
import { useState, useEffect } from "react";
import { useDispatch, useSelector } from "react-redux";
import CartItem from "./CartItems";
import img from "../../Images/Busybinder-logo.png";
import ProgressBar from "./Progressbar";

const Cart = () => {
  const [formData, setFormData] = useState({
    name: "",
    email: "",
    address: "",
    postalCode: "",
    phoneNumber: "",
    message: "",
  });
  const dispatch = useDispatch();
  const cartClickHandle = () => {
    dispatch(cartActions.toggleCart(false));
  };
  const windowSize = useSelector((state) => state.ui.screenSize);
  const cartItems = useSelector((state) => state.cart.items);
  const total = useSelector((state) => state.cart.totalAmount);

  const progress = useSelector((state) => state.ui.progress);
  const nextStep = () => {
    dispatch(uiActions.progressBarHandler("next"));
  };
  const prevStep = () => {
    dispatch(uiActions.progressBarHandler("prev"));
  };
  const [formErrors, setFormErrors] = useState({});
  const [isFormValid, setIsFormValid] = useState(false);

  const validateForm = () => {
    const errors = {};

    // Name validation
    if (!formData.name.trim()) {
      errors.name = "Name is required";
    }

    // Email validation
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!formData.email.trim()) {
      errors.email = "Email is required";
    } else if (!emailRegex.test(formData.email)) {
      errors.email = "Invalid email format";
    }

    // Address validation
    if (!formData.address.trim()) {
      errors.address = "Address is required";
    }

    // Postal code validation
    if (!formData.postalCode.trim()) {
      errors.postalCode = "Postal code is required";
    }

    // Phone number validation
    const phoneRegex = /^\d{10}$/; //  a 10-digit phone number
    if (!formData.phoneNumber.trim()) {
      errors.phoneNumber = "Phone number is required";
    } else if (!phoneRegex.test(formData.phoneNumber)) {
      errors.phoneNumber = "Invalid phone number format";
    }

    // Message is optional, so no validation needed

    setFormErrors(errors);
    return Object.keys(errors).length === 0;
  };

  useEffect(() => {
    setIsFormValid(validateForm());
  }, [formData]);

  const handleInputChange = (name, value) => {
    setFormData((prevData) => ({
      ...prevData,
      [name]: value,
    }));
  };

  const handleFormSubmit = (e) => {
    e.preventDefault();
    if (isFormValid) {
      console.log(formData);
      dispatch(uiActions.progressBarHandler("next"));
      dispatch(cartActions.checkoutHandler(formData));

      // Handle form submission
    } else {
      const errorMessages = Object.values(formErrors).filter(
        (error) => error !== ""
      );
      if (errorMessages.length > 0) {
        alert(
          `Please correct the following errors:\n${errorMessages.join("\n")}`
        );
      } else {
        alert("Please fill in all required fields.");
      }
    }
  };
  return (
    <>
      <div className={classes.backdrop} onClick={cartClickHandle}></div>
      <motion.div
        initial={{ opacity: 0, x: 300 }}
        animate={{ opacity: 1, x: 0 }}
        exit={{ opacity: 0, x: 300 }}
        open
        className={classes.menu}
        style={{ width: windowSize ? "50%" : "100%" }}
      >
        <div className={classes.hamburguerPosition}>
          <div className={classes.hamburguer} onClick={cartClickHandle}>
            <Hamburguer />
          </div>
        </div>
        <ProgressBar />
        {progress === 2 && (
          <form id="personalDataForm" onSubmit={handleFormSubmit}>
            <PersonalDetail
              formData={formData}
              onInputChange={handleInputChange}
              formErrors={formErrors}
            />
          </form>
        )}
        {cartItems.length > 0 ? (
          <ul className={classes.cartItems}>
            {progress === 1 &&
              cartItems.map((item) => (
                <CartItem
                  key={item.id + item.title}
                  item={{
                    id: item.itemId,
                    title: item.title,
                    quantity: item.totalQuantity,
                    totalPrice: item.totalPrice,
                    price: item.price,
                    img: img,
                  }}
                />
              ))}
            <div className={classes["cart-bottom"]}>
              <h4>
                Subtotal : <span>$ {total}</span>
              </h4>
              <div>
                {progress >= 2 && (
                  <button className={classes.checkout} onClick={prevStep}>
                    Previous
                  </button>
                )}
                {progress === 2 && (
                  <button
                    type="submit"
                    form="personalDataForm"
                    className={classes.checkout}
                  >
                    Next!
                  </button>
                )}
                {progress === 1 && (
                  <button className={classes.checkout} onClick={nextStep}>
                    Next
                  </button>
                )}
              </div>
            </div>
          </ul>
        ) : (
          <div className={classes["empty-section"]}>
            <div className={classes.bag}></div>
            <h2>Your Bag is empty</h2>
            <p>add items</p>
          </div>
        )}
      </motion.div>
    </>
  );
};

export default Cart;
