import { createSlice } from "@reduxjs/toolkit";

const cartSlice = createSlice({
  name: "cart",
  initialState: {
    cartIsVisible: false,
    menuIsVisible: false,
    items: [],
    totalQuantity: 0,
    totalAmount: 0.0, // Initialize as a number
    checkout: {
      name: "",
      email: "",
      address: "",
      postalCode: "",
      phoneNumber: "",
      message: "",
    },
  },
  reducers: {
    checkoutHandler(state, action) {
      state.checkout = action.payload;
    },
    toggleCart(state, action) {
      state.cartIsVisible = action.payload;
    },
    toggleMenu(state, action) {
      state.menuIsVisible = action.payload;
    },
    addItemtoCart(state, action) {
      const newItem = action.payload;
      const existingItem = state.items.find(
        (item) => item.itemId === newItem.id
      );

      // Ensure newItem.price is a number
      const price = parseFloat(newItem.price);
      if (isNaN(price)) {
        console.error("Invalid price:", newItem.price);
        return; // Exit if the price is invalid
      }

      if (!existingItem) {
        // Add new item to the cart
        state.items.push({
          itemId: newItem.id,
          price: price, // Store price as a number
          totalQuantity: 1,
          totalPrice: price.toFixed(2), // Set totalPrice formatted to two decimal places
          title: newItem.title,
        });
      } else {
        // Update existing item's quantity and totalPrice
        existingItem.totalQuantity++;
        existingItem.totalPrice = (
          existingItem.price * existingItem.totalQuantity
        ).toFixed(2); // Update totalPrice formatted to two decimal places
      }

      state.totalQuantity++;
      // Recalculate totalAmount formatted to two decimal places
      state.totalAmount = state.items
        .reduce(
          (total, item) => total + parseFloat(item.totalPrice), // Ensure to parse to float
          0
        )
        .toFixed(2); // Format to two decimal places
    },
    removeItemFromCart(state, action) {
      const id = action.payload;
      const existingItem = state.items.find((item) => item.itemId === id);

      if (existingItem) {
        state.totalQuantity--;
        if (existingItem.totalQuantity === 1) {
          // Remove item from cart if quantity is 1
          state.items = state.items.filter((item) => item.itemId !== id);
        } else {
          // Decrease quantity and recalculate totalPrice
          existingItem.totalQuantity--;
          existingItem.totalPrice = (
            existingItem.price * existingItem.totalQuantity
          ).toFixed(2); // Update totalPrice formatted to two decimal places
        }
      }

      // Recalculate totalAmount after item removal formatted to two decimal places
      state.totalAmount = state.items
        .reduce(
          (total, item) => total + parseFloat(item.totalPrice), // Ensure to parse to float
          0
        )
        .toFixed(2); // Format to two decimal places
    },
  },
});

export const cartActions = cartSlice.actions;
export default cartSlice;
