import React, { useState } from "react";
import classes from "./AddProduct.module.css";
import { db } from "../../Firebase/firebase";
import { addDoc, collection } from "firebase/firestore";

const AddProduct = () => {
  const [formData, setFormData] = useState({
    title: "",
    price: 0,
    type: "",
    id: "",
  });
  const productsCollection = collection(db, "Products");

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData({
      ...formData,
      [name]: value,
    });
  };

  const submitForm = async (e) => {
    const randomNumber = Math.floor(Math.random() * 1000); // Generate a random number
    const id = `${formData.type}-${formData.title}-${randomNumber}`; // Create the ID

    // Add the document to the Firestore collection
    try {
      await addDoc(productsCollection, {
        title: formData.title,
        price: formData.price,
        type: formData.type,
        id: id,
      });
      console.log("Document added with ID: ", id);
    } catch (error) {
      console.error("Error adding document: ", error);
    }
  };

  return (
    <div>
      <div className={classes.wrapper}>
        <hr className={classes.sep} />
        <div className={classes.group}>
          <input
            type="text"
            name="title"
            required
            onChange={handleChange}
            value={formData.name}
          />
          <span className={classes.highlight}></span>
          <span className={classes.bar}></span>
          <label>Name</label>
        </div>
        <div className={classes.group}>
          <input
            type="number"
            name="price"
            required
            onChange={handleChange}
            value={formData.price}
          />
          <span className={classes.highlight}></span>
          <span className={classes.bar}></span>
          <label>Price</label>
        </div>
        <div className={classes.group}>
          <input
            type="text"
            name="type"
            required
            onChange={handleChange}
            value={formData.type}
          />
          <span className={classes.highlight}></span>
          <span className={classes.bar}></span>
          <label>Type</label>
        </div>

        <button type="button" onClick={submitForm}>
          Enviar
        </button>
      </div>
    </div>
  );
};

export default AddProduct;
