import React, { useState, useEffect } from "react";
import classes from "./AddProduct.module.css";
import { db } from "../../Firebase/firebase";
import { updateDoc, doc, collection, deleteDoc } from "firebase/firestore";

const EditProduct = ({ item, onSave }) => {
  const [formData, setFormData] = useState({
    title: "",
    price: 0,
    type: "",
    id: "",
  });

  // Initialize formData with item data when item changes
  useEffect(() => {
    if (item) {
      setFormData({
        title: item.title || "",
        price: item.price || 0,
        type: item.type || "",
        id: item.id || "",
      });
    }
  }, [item]);

  const productsCollection = collection(db, "Products");

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData({
      ...formData,
      [name]: value,
    });
  };

  const updateData = async () => {
    const { title, price, type, id } = formData; // Use values from formData
    const newFields = {
      title,
      price: parseFloat(price), // Ensure price is a number
      type,
    };
    const userDoc = doc(productsCollection, id);

    try {
      await updateDoc(userDoc, newFields);
      onSave({ ...item, ...newFields }); // Call onSave to update local state
    } catch (error) {
      console.error("Error updating document: ", error);
    }
  };
  //   delete Data
  const deleteAlbum = async (id) => {
    if (typeof id !== "string") {
      console.error("Invalid id type:", typeof id);
      return;
    }
    const userDoc = doc(productsCollection, id);
    await deleteDoc(userDoc);
  };
  return (
    <div>
      <div className={classes.wrapper}>
        <hr className={classes.sep} />
        <div className={classes.group}>
          <input
            type="text"
            name="title"
            required
            onChange={handleChange}
            value={formData.title} // Use formData for value
          />
          <span className={classes.highlight}></span>
          <span className={classes.bar}></span>
          <label>Name</label>
        </div>
        <div className={classes.group}>
          <input
            type="number"
            name="price"
            required
            onChange={handleChange}
            value={formData.price} // Use formData for value
          />
          <span className={classes.highlight}></span>
          <span className={classes.bar}></span>
          <label>Price</label>
        </div>
        <div className={classes.group}>
          <input
            type="text"
            name="type"
            required
            onChange={handleChange}
            value={formData.type} // Use formData for value
          />
          <span className={classes.highlight}></span>
          <span className={classes.bar}></span>
          <label>Type</label>
        </div>
        <button type="button" onClick={updateData}>
          Send
        </button>
        <button
          onClick={() => {
            if (item && item.id) {
              deleteAlbum(item.id.toString());
            } else {
              console.error("Invalid item or item id");
            }
          }}
        >
          Delete
        </button>
      </div>
    </div>
  );
};

export default EditProduct;
