import React from "react";
import classes from "./CartItems.module.css";
import { useDispatch } from "react-redux";
import { cartActions } from "../../store/cart-slice";

const CartItem = (props) => {
  const dispatch = useDispatch();

  const addHandler = () => {
    dispatch(
      cartActions.addItemtoCart({
        id: props.item.id,
        price: props.item.price,
        title: props.item.title,
      })
    );
  };

  const removeHandler = () => {
    dispatch(cartActions.removeItemFromCart(props.item.id));
  };

  return (
    <li
      key={props.item.itemId + props.item.title}
      className={classes["cart-item"]}
    >
      <div>
        <div>
          <img className={classes.image} src={props.item.img} />
          <h2>{props.item.title}</h2>
        </div>
        <div className={classes.summary}>
          <span className={classes.price}>${props.item.price}</span>
          <span className={classes.amount}>x{props.item.quantity}</span>
          <span className={classes.totalPrice}>= ${props.item.totalPrice}</span>
        </div>
      </div>
      <div className={classes.actions}>
        <button onClick={removeHandler}>−</button>
        <button onClick={addHandler}>+</button>
      </div>
    </li>
  );
};

export default CartItem;
