import React, { useState, useEffect } from "react";
import classes from "./PopularAlbuns.module.css";
import PopularItems from "./PopularItems";
import AddProduct from "../Admin/AddProduct";
import { db } from "../../Firebase/firebase";
import { collection, getDocs } from "firebase/firestore";
import Modal from "../Modal/Modal"; // Ensure the correct path to your Modal component
import EditProduct from "../Admin/UpdateProduct";

const PopularAlbuns = () => {
  const productsCollection = collection(db, "Products");
  const [items, setItems] = useState([]);
  const [edit, setEdit] = useState(false);
  const [currentItem, setCurrentItem] = useState(null); // State to hold the item being edited

  const editHandler = (item) => {
    setCurrentItem(item); // Set the current item to be edited
    setEdit(true); // Open the modal
  };

  useEffect(() => {
    const fetchData = async () => {
      const data = await getDocs(productsCollection);
      setItems(data.docs.map((doc) => ({ ...doc.data(), id: doc.id })));
    };
    fetchData();
  }, []);

  const handleSave = () => {
    console.log("Saving item:", currentItem);
    // Here you would typically update the item in your database
    setEdit(false); // Close the modal after saving
  };

  return (
    <div>
      <h1 className={classes.header}>Popular Albums</h1>
      <div className={classes.list}>
        {items.map((item) => (
          <ul className={classes.albuns} key={item.id}>
            <PopularItems
              id={item.id}
              title={item.title}
              img={item.img}
              type={item.type}
              price={item.price}
            />
            <button onClick={() => editHandler(item)}>Edit</button>
          </ul>
        ))}
      </div>
      {edit &&
        currentItem && ( // Ensure currentItem is not null
          <Modal
            isOpen={edit}
            onClose={() => setEdit(false)} // Close the modal
            title="Edit Item"
            item={currentItem} // Pass the current item to the modal
          >
            <EditProduct item={currentItem}></EditProduct>
          </Modal>
        )}
      <AddProduct />
    </div>
  );
};

export default PopularAlbuns;
