import React from "react";
import Busybinder from "../../Images/Busybinder-logo.png";
import WelcomeComponent from "../UI/Button";
import { useDispatch } from "react-redux";
import { cartActions } from "../../store/cart-slice";

import classes from "./PopularItems.module.css";

const PopularItems = (props) => {
  const dispatch = useDispatch();
  const { id, title, price } = props;
  const addItemtoCart = () => {
    dispatch(
      cartActions.addItemtoCart({
        totalQuantity: 1,
        id: id,
        title: title,
        price: price,
      })
    );
  };

  return (
    <li className={classes.movie}>
      <img className={classes.itemImg} src={Busybinder}></img>
      <p className={classes.type}>{props.type}</p>
      <p className={classes.title}>{props.title}</p>
      <p className={classes.price}>${props.price}</p>
      <div className={classes.button} onClick={addItemtoCart}>
        <WelcomeComponent button="Buy" />
      </div>
    </li>
  );
};

export default PopularItems;
